def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than ``n``.
    Uses a straightforward Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    # is_prime[i] = 1 if i is assumed prime
    is_prime = bytearray(b'\x01') * n
    is_prime[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            # start marking from p*p
            start = p * p
            step = p
            for multiple in range(start, n, step):
                is_prime[multiple] = 0
    # sum of bytes gives count of primes < n
    return sum(is_prime)

