def solve(grid):
    """Count the number of islands (4-directionally connected 1s) in a grid.
    The grid may be non-rectangular; missing entries are treated as 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    count = 0

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            # Check bounds for row
            if x < 0 or x >= rows:
                continue
            # Check column bounds for this row
            if y < 0 or y >= len(grid[x]):
                continue
            if grid[x][y] != 1:
                continue
            visited.add((x, y))
            # explore neighbours
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))

    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

