    return lo

def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * (((limit - start) // step) + 1)
    return sum(sieve)

def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses Bareiss algorithm for exact integer result.
    Empty matrix returns 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    if any(len(row) != n for row in matrix):
        raise ValueError("Matrix must be square")
    # Deep copy
    a = [list(row) for row in matrix]
    if n == 1:
        return a[0][0]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Pivot if zero
        if a[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

