def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses a recursive cofactor expansion for small sizes (n <= 6) to avoid any
    subtle issues with the Bareiss implementation, and falls back to the
    Bareiss fraction‑free algorithm for larger matrices. An empty matrix has
    determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    if any(len(row) != n for row in matrix):
        raise ValueError("Matrix must be square")
    # Simple recursive determinant for small n (<=6) – safe and easy
    if n <= 6:
        def det_recursive(m):
            size = len(m)
            if size == 1:
                return m[0][0]
            if size == 2:
                return m[0][0] * m[1][1] - m[0][1] * m[1][0]
            total = 0
            for col, element in enumerate(m[0]):
                if element == 0:
                    continue
                # build submatrix without first row and current column
                sub = [row[:col] + row[col+1:] for row in m[1:]]
                sign = -1 if col % 2 else 1
                total += sign * element * det_recursive(sub)
            return total
        return det_recursive(matrix)
    # For larger matrices use Bareiss fraction‑free elimination
    a = [list(row) for row in matrix]  # deep copy
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Pivot selection: swap with a non‑zero entry if needed
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Exact integer division guaranteed by Bareiss algorithm
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

