def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a two‑element list/tuple [start, end].
    A meeting may start exactly when another ends.
    Zero‑length meetings (start == end) are attendable and do not consume time,
    so all of them can be counted. Intervals where start > end are ignored.
    """
    if not meetings:
        return 0
    zero_len = 0
    positive = []  # intervals with start < end
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        start, end = m[0], m[1]
        if start > end:
            continue  # ignore invalid intervals
        if start == end:
            zero_len += 1
        else:
            positive.append((start, end))
    # Greedy selection for positive‑length meetings
    positive.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in positive:
        if start >= last_end:
            count += 1
            last_end = end
    return count + zero_len

