    """0/1 knapsack returning the maximum total value.
    If the capacity exceeds the total weight of all items, the answer is simply
    the sum of all values, avoiding an unnecessarily large DP array.
    """
    if capacity <= 0 or not weights:
        return 0
    total_weight = sum(weights)
    if capacity >= total_weight:
        return sum(values)
    # 1D DP over capacity
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        # iterate backwards to prevent reuse
