def solve(n: int) -> int:
    if n <= 2:
        return 0
    import math
    size = n // 2
    is_prime = bytearray(b'\x01') * size
    is_prime[0] = 0
    limit = int(math.isqrt(n - 1))
    max_i = (limit - 1) // 2
    for i in range(1, max_i + 1):
        if is_prime[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            step = p
            if start < size:
                count = (size - start - 1) // step + 1
                if count > 0:
                    is_prime[start::step] = b'\x00' * count
    return 1 + sum(is_prime)

