def solve(s: str) -> str:
    """Return the longest palindromic substring of *s*.
    If there are multiple substrings of maximum length, the one with the smallest
    starting index is returned.
    """
    n = len(s)
    if n == 0:
        return ''
    # Helper to expand around a center and return (start, end) inclusive
    def expand(l: int, r: int) -> tuple[int, int]:
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        # after loop, l and r are one step beyond the palindrome
        return l + 1, r - 1
    best_start, best_end = 0, 0  # inclusive indices
