def solve(grid):
    """Return the number of islands in a binary grid.
    An island is a group of adjacent 1s connected vertically or horizontally.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Support possibly jagged rows by checking each row's length during traversal.
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds check
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            # explore neighbors
            stack.append((i - 1, j))
            stack.append((i + 1, j))
            stack.append((i, j - 1))
            stack.append((i, j + 1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

