def solve(s: str) -> bool:
    """Return True if brackets in *s* are balanced and properly nested.
    Considers parentheses (), square brackets [], and curly braces {}. All other
    characters are ignored.
    """
    stack = []
    opening = {'(', '[', '{'}
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

