def solve(line):
    """Parse a single CSV line into fields.
    Supports double-quoted fields where commas are literal and "" represents a literal double quote.
    Returns a list of field strings.
    """
    fields = []
    field = []
    i = 0
    n = len(line)
    in_quote = False
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i+1] == '"':
                    field.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quote = False  # end of quoted field
            else:
                field.append(ch)
        else:
            if ch == '"':
                # start quoted field
                in_quote = True
            elif ch == ',':
                # field separator
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        i += 1
    # Append last field (even if line ends with a comma, field will be empty)
    fields.append(''.join(field))
    return fields

