def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss algorithm (fraction-free Gaussian elimination) to compute
    the determinant exactly as an integer. An empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # make a deep copy to avoid mutating input
    A = [row[:] for row in matrix]
    det = 1
    # Bareiss algorithm
    for k in range(n - 1):
        # Find a non-zero pivot if current pivot is zero
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det  # row swap changes sign
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Compute without fractions using previous pivot
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j])
                if k > 0:
                    A[i][j] //= A[k - 1][k - 1]
            A[i][k] = 0
    det *= A[n - 1][n - 1]
    return det

